package services
import("testing";"time";"fluxo/models")
func TestPriorityWeights(t *testing.T){now:=time.Now();base:=models.Tarefa{Prioridade:"media",Origem:"Protocolo",Status:"pendente",AtualizadoEm:now,Prazo:now.Add(72*time.Hour)};urgent:=base;urgent.Prioridade="urgente";if PriorityScore(urgent,now)<=PriorityScore(base,now){t.Fatal("urgency must increase score")};stale:=base;stale.AtualizadoEm=now.Add(-300*24*time.Hour);if PriorityScore(stale,now)-PriorityScore(base,now)!=30{t.Fatal("waiting bonus must cap at 30")};late:=base;late.Prazo=now.Add(-time.Hour);if PriorityScore(late,now)-PriorityScore(base,now)!=25{t.Fatal("overdue bonus must be 25")};done:=late;done.Status="concluida";if PriorityScore(done,now)!=PriorityScore(base,now){t.Fatal("completed tasks receive no overdue bonus")}}
